import React, { useState, useEffect } from "react";
import { Routes, Route, useNavigate } from "react-router-dom";

import LoginForm from "./LoginForm";
import RegisterForm from "./RegisterForm";
import DepositForm from "./DepositForm";
import WithdrawForm from "./WithdrawForm";
import Home from "./Home";
import AdminDepositRequests from "./AdminDepositRequests";
import AdminWithdrawRequests from "./AdminWithdrawRequests";
import UserHistory from "./UserHistory";
import AdminUserHistory from "./AdminUserHistory";
import Match from "./components/Match";
import LudoBoard from "./components/LudoBoard";

function App() {
  const [token, setToken] = useState(null);
  const [email, setEmail] = useState("");
  const [role, setRole] = useState(null);
  const [showRegister, setShowRegister] = useState(false);
  const [gameData, setGameData] = useState(null);

  const navigate = useNavigate();

  useEffect(() => {
    const savedToken = localStorage.getItem("authToken");
    if (savedToken) setToken(savedToken);
  }, []);

  useEffect(() => {
    const fetchUserInfo = async () => {
      if (!token) return;

      try {
        const res = await fetch("http://localhost:8080/api/user/profile", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        });

        if (!res.ok) throw new Error("Failed to fetch user profile");

        const user = await res.json();
        setEmail(user.email || "");
        setRole(user.role || "");
      } catch (err) {
        console.error("User profile fetch error:", err);
        handleLogout();
      }
    };

    fetchUserInfo();
  }, [token]);

  const handleLogin = (token) => {
    localStorage.setItem("authToken", token);
    setToken(token);
    navigate("/");
  };

  const handleLogout = () => {
    localStorage.removeItem("authToken");
    setToken(null);
    setEmail("");
    setRole(null);
    navigate("/");
  };

  const handleRegisterSuccess = () => {
    setShowRegister(false);
  };

  const isAdmin = (role || "").toLowerCase() === "admin";

  if (!token) {
    return showRegister ? (
      <RegisterForm
        onRegisterSuccess={handleRegisterSuccess}
        goToLogin={() => setShowRegister(false)}
      />
    ) : (
      <LoginForm
        onLogin={handleLogin}
        onRegisterClick={() => setShowRegister(true)}
      />
    );
  }

  if (role === null) {
    return <p style={{ padding: "20px" }}>লোড হচ্ছে...</p>;
  }

  return (
    <Routes>
      <Route
        path="/"
        element={
          <Home
            token={token}
            email={email}
            onLogout={handleLogout}
            onShowDeposit={() => navigate("/deposit")}
            onShowWithdraw={() => navigate("/withdraw")}
            onShowAdminDepositRequests={() => navigate("/admin-deposits")}
            onShowAdminWithdraw={() => navigate("/admin-withdraws")}
            onShowHistory={() => navigate("/history")}
            onShowAdminUserHistory={() => navigate("/admin-user-history")}
            onShowLudoMatch={() => navigate("/match")}
            onShowLudoBoard={() => navigate("/game")}
          />
        }
      />

      <Route
        path="/deposit"
        element={<DepositForm token={token} onCancel={() => navigate("/")} />}
      />
      <Route
        path="/withdraw"
        element={<WithdrawForm token={token} onCancel={() => navigate("/")} />}
      />
      <Route
        path="/admin-deposits"
        element={
          isAdmin ? (
            <AdminDepositRequests onCancel={() => navigate("/")} />
          ) : (
            <p>Unauthorized</p>
          )
        }
      />
      <Route
        path="/admin-withdraws"
        element={
          isAdmin ? (
            <AdminWithdrawRequests onCancel={() => navigate("/")} />
          ) : (
            <p>Unauthorized</p>
          )
        }
      />
      <Route
        path="/history"
        element={<UserHistory onCancel={() => navigate("/")} />}
      />
      <Route
        path="/admin-user-history"
        element={
          isAdmin ? (
            <AdminUserHistory onCancel={() => navigate("/")} />
          ) : (
            <p>Unauthorized</p>
          )
        }
      />
      <Route
        path="/match"
        element={
          <Match
            userEmail={email}
            onGameStart={(gameInfo) => {
              setGameData(gameInfo);
              navigate("/game");
            }}
          />
        }
      />
      <Route
        path="/game"
        element={
          gameData ? (
            <LudoBoard
              userEmail={email}
              game={gameData}
              onCancel={() => navigate("/")}
            />
          ) : (
            <p>❌ কোনো গেম পাওয়া যায়নি।</p>
          )
        }
      />
    </Routes>
  );
}

export default App;
